import{_ as t,o as i,c as a,a2 as o}from"./chunks/framework.D5wUhsuj.js";const u=JSON.parse('{"title":"PhyAgentOS Developer Manual","description":"","frontmatter":{},"headers":[],"relativePath":"en/03-developer-manual.md","filePath":"en/03-developer-manual.md"}'),n={name:"en/03-developer-manual.md"};function s(l,e,r,d,c,p){return i(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="phyagentos-developer-manual" tabindex="-1">PhyAgentOS Developer Manual <a class="header-anchor" href="#phyagentos-developer-manual" aria-label="Permalink to &quot;PhyAgentOS Developer Manual&quot;">​</a></h1><p><a href="/docs/zh/03-developer-manual">中文</a> · <a href="/docs/en/">Documentation index</a></p><blockquote><p>Documentation version: 1.0.0.</p></blockquote><h2 id="_1-development-invariants" tabindex="-1">1. Development invariants <a class="header-anchor" href="#_1-development-invariants" aria-label="Permalink to &quot;1. Development invariants&quot;">​</a></h2><ol><li>Robot execution has one physical path: <code>ForgeToolClient → Gateway Tool API → ToolEndpoint</code>.</li><li>AgentTask aggregates planning, evidence, and verdicts; it never executes the robot.</li><li><code>binding_id</code>, <code>task_id</code>, <code>revision_id</code>, record ID, <code>caller_id</code>, <code>invocation_id</code>, and <code>attempt_id</code> are distinct.</li><li>Forge ToolResult and invocation events are authoritative execution facts.</li><li>Action/Session admission, cancel/stop acceptance, timeout, and <code>unknown</code> do not prove physical stop.</li><li>General Agent tools, verification, experience, evolution, and dynamic MCP remain independent.</li><li>Runtime artifacts are installed only after bounded archive and digest verification.</li></ol><h2 id="_2-module-map" tabindex="-1">2. Module map <a class="header-anchor" href="#_2-module-map" aria-label="Permalink to &quot;2. Module map&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Module</th><th style="text-align:left;">Responsibility</th></tr></thead><tbody><tr><td style="text-align:left;"><code>agent/loop.py</code></td><td style="text-align:left;">Existing Agent loop, general tools, dynamic MCP, Forge tool registration, context, and lifecycle</td></tr><tr><td style="text-align:left;"><code>agent/tools/forge_tool_api.py</code></td><td style="text-align:left;">Governed Query/Action/Session Tool API Agent wrappers</td></tr><tr><td style="text-align:left;"><code>agent/tools/forge_task.py</code></td><td style="text-align:left;">Five AgentTask lifecycle tools</td></tr><tr><td style="text-align:left;"><code>forge/tool_client.py</code></td><td style="text-align:left;">Strict asynchronous HTTP client and response validation</td></tr><tr><td style="text-align:left;"><code>forge/binding.py</code>, <code>forge/task.py</code></td><td style="text-align:left;">Immutable Runtime/ToolSpec binding, AgentTask models/store, evidence, verification, and recovery</td></tr><tr><td style="text-align:left;"><code>forge/observation.py</code>, <code>forge/evidence.py</code></td><td style="text-align:left;">Best-effort image/state collection and artifact writing</td></tr><tr><td style="text-align:left;"><code>skill_runtime/</code></td><td style="text-align:left;">Manifest, catalog, safe archive, installer, Registry, state, Runtime manager, and availability</td></tr><tr><td style="text-align:left;"><code>agent/experience/</code></td><td style="text-align:left;">Activation, episodes, assessment, Lessons, Skill candidates, and evolution</td></tr><tr><td style="text-align:left;"><code>verification/</code></td><td style="text-align:left;">Public task, evidence, request, and verdict contracts plus verification service</td></tr></tbody></table><h2 id="_3-forge-tool-api-client" tabindex="-1">3. Forge Tool API client <a class="header-anchor" href="#_3-forge-tool-api-client" aria-label="Permalink to &quot;3. Forge Tool API client&quot;">​</a></h2><p><code>ForgeToolClient</code> accepts only JSON object envelopes with <code>ok=true</code> and object-valued <code>data</code>. Errors preserve HTTP status, error code, retryability, and any returned invocation identity.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Operation</th><th style="text-align:left;">HTTP contract</th></tr></thead><tbody><tr><td style="text-align:left;">List Tools</td><td style="text-align:left;"><code>GET /tools</code> → 200</td></tr><tr><td style="text-align:left;">Read ToolSpec</td><td style="text-align:left;"><code>GET /tools/{tool_id}</code> → 200</td></tr><tr><td style="text-align:left;">Read context</td><td style="text-align:left;"><code>GET /tools/{tool_id}/context</code> → 200</td></tr><tr><td style="text-align:left;">Invoke Query</td><td style="text-align:left;">resolve ToolSpec, then <code>POST /tools/{endpoint_id}/{operation}:invoke</code> → 200</td></tr><tr><td style="text-align:left;">Admit Action</td><td style="text-align:left;"><code>POST /tools/{tool_id}:invoke</code> → 202</td></tr><tr><td style="text-align:left;">Action status</td><td style="text-align:left;"><code>GET /invocations/{invocation_id}</code> → 200</td></tr><tr><td style="text-align:left;">Action result</td><td style="text-align:left;"><code>GET /invocations/{invocation_id}/result</code> → 200 or pending 202</td></tr><tr><td style="text-align:left;">Request cancel</td><td style="text-align:left;"><code>POST /invocations/{invocation_id}/cancel</code> → 200 or accepted 202</td></tr><tr><td style="text-align:left;">Admit Session</td><td style="text-align:left;"><code>POST /tools/{tool_id}:invoke</code> → 202</td></tr><tr><td style="text-align:left;">Stop Session</td><td style="text-align:left;"><code>POST /invocations/{invocation_id}/stop</code> → 200 or accepted 202</td></tr></tbody></table><p>Path components are percent-encoded. PAOS supplies <code>caller_id</code> and persists it with the intent before Action/Session admission. Admission must contain a non-empty <code>invocation_id</code>; Action also requires <code>attempt_id</code>. A timeout leaves an unknown record and recovery never repeats the POST.</p><h2 id="_4-agent-facing-tools" tabindex="-1">4. Agent-facing tools <a class="header-anchor" href="#_4-agent-facing-tools" aria-label="Permalink to &quot;4. Agent-facing tools&quot;">​</a></h2><p>Task lifecycle:</p><ul><li><code>forge_task_create(task_description, verification, activation_id)</code>;</li><li><code>forge_task_get(task_id)</code>;</li><li><code>forge_task_begin_revision(task_id, reason)</code>;</li><li><code>forge_task_finalize(task_id)</code>;</li><li><code>forge_task_cancel(task_id, reason?)</code>.</li></ul><p>Tool transport:</p><ul><li><code>forge_tool_context(tool_id)</code>;</li><li><code>forge_tool_query(tool_id, arguments, task_id?, timeout_ms?)</code>;</li><li><code>forge_tool_start_action(task_id, tool_id, arguments, timeout_ms?)</code>;</li><li><code>forge_tool_action_status(task_id, invocation_id)</code>;</li><li><code>forge_tool_action_result(task_id, invocation_id)</code>;</li><li><code>forge_tool_cancel_action(task_id, invocation_id)</code>;</li><li><code>forge_tool_start_session(task_id, tool_id, arguments, ownership)</code>;</li><li><code>forge_tool_session_status/result/stop_session(task_id, invocation_id)</code>.</li></ul><p>Diagnostic Query and bound calls invoke the same HTTP methods. Every mutating or task-attributed wrapper validates ownership and the frozen Tool binding before network access. Tool wrappers must never invent a Gateway identity or result.</p><h2 id="_5-agenttask-contracts-and-transactions" tabindex="-1">5. AgentTask contracts and transactions <a class="header-anchor" href="#_5-agenttask-contracts-and-transactions" aria-label="Permalink to &quot;5. AgentTask contracts and transactions&quot;">​</a></h2><p><code>AgentTaskRecord</code> contains a stable ID, task description, <code>TaskVerificationContract</code>, status, append-only PlanRevisions, evidence references, verification attempts, cancellation state, and timestamps. Each <code>PlanRevision</code> contains its own Tool records, verdict, and verification attempts.</p><p><code>AgentTaskStore</code> uses SQLite WAL and <code>BEGIN IMMEDIATE</code>. Creation queries for any non-terminal task inside the same transaction, enforcing one global active slot across processes. Updates write the complete validated record and an append-only event. Callers do not modify tables directly.</p><p>Terminal task states are <code>succeeded</code>, <code>failed</code>, and <code>cancelled</code>. Non-terminal states are <code>executing</code>, <code>cancelling</code>, and <code>awaiting_replan</code>. Tool status <code>unknown</code> is terminal for aggregate accounting but is a failure, not evidence of stop.</p><h2 id="_6-bound-execution-lifecycle" tabindex="-1">6. Bound execution lifecycle <a class="header-anchor" href="#_6-bound-execution-lifecycle" aria-label="Permalink to &quot;6. Bound execution lifecycle&quot;">​</a></h2><ol><li>Activate the primary Skill and freeze its Runtime/ToolSpec candidate into AgentTask revision 1.</li><li>On the first bound physical execution, perform best-effort before-capture.</li><li>Invoke Query or admit Action/Session through ForgeToolClient.</li><li>Persist caller intent before admission and then retain Gateway invocation/attempt references.</li><li>Update asynchronous records only from authoritative status/result responses.</li><li>After every task-owned execution is terminal, perform after-capture on finalize.</li><li>Aggregate Tool records, evidence, and the task contract for verification.</li><li>Persist task and revision verdicts; schedule one terminal experience episode.</li></ol><p>Once a record is terminal, later observations do not rewrite it. Cancellation responses are stored, but <code>requested</code> or <code>accepted</code> leaves the task in <code>cancelling</code> until reconciliation and explicit finalization.</p><h2 id="_7-verification-and-recovery" tabindex="-1">7. Verification and recovery <a class="header-anchor" href="#_7-verification-and-recovery" aria-label="Permalink to &quot;7. Verification and recovery&quot;">​</a></h2><p><code>TaskVerificationContract</code> remains the public user-level contract. The verifier receives goal, criteria, constraints, the frozen Skill binding, PlanRevisions, ToolExecutionRecords, Gateway terminal results, before/after evidence, task history, and frozen Skill-scoped advisory Lessons.</p><p>In recovery mode, a valid <code>replan_required</code> verdict moves the task to <code>awaiting_replan</code> with a deadline. <code>begin_revision</code> checks the same <code>task_id</code>, replan budget, deadline, and task state, then appends a revision. Earlier attempts remain visible to experience analysis. Verifier exceptions are persisted as failed attempts; audit preserves execution semantics, while enforce/recovery fail.</p><h2 id="_8-evidence-and-retention" tabindex="-1">8. Evidence and retention <a class="header-anchor" href="#_8-evidence-and-retention" aria-label="Permalink to &quot;8. Evidence and retention&quot;">​</a></h2><p>Evidence paths are workspace-relative and written atomically. Before semantic verification, the bundle identity, association quality, completeness, capture window, and required kinds and sources are checked. Retained artifacts are then validated for path containment, byte size, SHA-256, media type, and structured JSON where applicable. The evidence bundle records capture quality and errors rather than presenting best-effort collection as authoritative.</p><p>Retention can remove entity bytes according to policy, but it must preserve the task record, execution references, bundle metadata, and tombstone information required for audit.</p><h2 id="_9-skill-runtime-contracts" tabindex="-1">9. Skill Runtime contracts <a class="header-anchor" href="#_9-skill-runtime-contracts" aria-label="Permalink to &quot;9. Skill Runtime contracts&quot;">​</a></h2><p>A <code>skill.yaml</code> manifest must use <code>manifest_version: 2</code>, a directory-safe name/version, a relative Skill document, an HTTP(S) <code>gateway_url</code>, non-empty required Tools, at least one profile, and strict known fields. Registry-resolved nodes require artifact identity, version, platform, architecture, archive type, one root executable entrypoint, and SHA-256.</p><p>Archive validation rejects absolute/traversing paths, links, duplicate/colliding paths, oversized files, expansion-limit violations, missing inventory entries, and digest mismatches. Skill and Node installers stage content, validate it, then atomically replace the target with rollback support.</p><p>RuntimeManager:</p><ol><li>resolves the installed Skill and profile;</li><li>materializes the locked environment without mutating installed nodes; its digest covers the exact dataflow path and SHA-256 of every regular file beside that dataflow;</li><li>checks the Dora CLI, dataflow, required files, and environment;</li><li>refuses to adopt an unmanaged Gateway already using the address;</li><li>persists <code>starting</code> and runs the optional Bundle start hook as <code>bash &lt;bundle&gt;/start.sh &lt;name&gt; &lt;version&gt;</code> with inherited stdio;</li><li>checks the local Dora services, runs <code>dora up</code> when needed, and starts the named flow;</li><li>waits for flow, <code>GET /tools</code>, and all required Tool contexts;</li><li>persists running/failed/stopped state and lifecycle logs.</li></ol><p>Dataflow rendering resolves <code>FORGE_RUNTIME_BIN</code>, <code>PAOS_SKILL_ROOT</code>, <code>PAOS_SKILL_NAME</code>, and <code>PAOS_SKILL_VERSION</code>; the two Skill identity values are also supplied to Dora process environments. Start, stop, Skill install/update commit, and removal share a non-blocking per-Skill cross-process lock. Status preserves <code>starting</code> while that lock proves startup is still active, while a stale unlocked <code>starting</code> state is reconciled normally.</p><p>The current Forge Skill compatibility baseline is Dora CLI v0.4.1 with <code>dora-message</code> v0.7.0. RuntimeManager requires compatible command behavior but does not enforce an exact semantic version; operators must prevent a mismatched coordinator/daemon from being reused. Dora is a host runtime prerequisite, not a Python dependency and not part of a Skill Bundle.</p><p>A normal stop is rejected while non-terminal invocations, Sessions, or task bindings remain tracked. Force stop records an audit event and does not change invocation truth.</p><h2 id="_10-registry-and-availability" tabindex="-1">10. Registry and availability <a class="header-anchor" href="#_10-registry-and-availability" aria-label="Permalink to &quot;10. Registry and availability&quot;">​</a></h2><p>Artifacts require an expected size and SHA-256 before entering the cache. Static indexes provide both values directly. A Registry Node may omit its duplicate digest and size fields: the verified Skill lock supplies the expected digest, and the client resolves the size from Registry metadata or the direct-download endpoint. Any Registry digest that is present must match the lock. Resumed downloads are verified again before installation. An empty Registry URL permits only local bundles or an explicit static index. <code>PAOS_RESOURCE_REGISTRY_URL</code> overrides <code>resourceRegistry.url</code>. The public Registry lookup is name-based. A requested CLI version is validated against the downloaded Skill manifest before Node resolution rather than appended to the Registry URL.</p><p><code>discover_active_runtime</code> reconciles persisted state, Dora flow, Gateway health, and required Tool contexts. Its availability provider flows through SkillsLoader, ExperienceCoordinator, and SkillActivationManager. Skill discovery order is workspace, installed, built-in.</p><h2 id="_11-experience-and-evolution-integration" tabindex="-1">11. Experience and evolution integration <a class="header-anchor" href="#_11-experience-and-evolution-integration" aria-label="Permalink to &quot;11. Experience and evolution integration&quot;">​</a></h2><p>All Agent tool calls remain recorded. Frozen binding/version fields attach AgentTask, revision, invocation, and attempt references. The outcome source maps each revision verdict to its last execution record so a recovered task preserves both failed and successful semantic attempts.</p><p>Generated Lessons and Skill updates remain subject to redaction, scope, support thresholds, abstraction checks, managed-block replacement, atomic writes, reload validation, and rollback. Evolution failures remain fail-open.</p><h2 id="_12-extension-workflows" tabindex="-1">12. Extension workflows <a class="header-anchor" href="#_12-extension-workflows" aria-label="Permalink to &quot;12. Extension workflows&quot;">​</a></h2><p>To add a robot capability:</p><ol><li>implement or package the ToolEndpoint operation;</li><li>publish a Query, Action, or Session ToolSpec with exact schemas and binding;</li><li>define operation <code>max_concurrency</code> in Gateway;</li><li>add the locked node and profile references to a manifest-v2 Bundle;</li><li>test binding drift, context, invocation, pending, terminal, cancel/stop, ownership, and unknown outcomes;</li><li>add workflow guidance to a Skill without embedding task-specific coordinates or secrets.</li></ol><p>Do not create a second PAOS execution protocol, direct Agent-to-Dora calls, or a cross-Tool lease. A new Agent tool is justified only when the generic task and Tool API tools cannot express the capability.</p><h2 id="_13-test-gates" tabindex="-1">13. Test gates <a class="header-anchor" href="#_13-test-gates" aria-label="Permalink to &quot;13. Test gates&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ruff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PhyAgentOS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compileall</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PhyAgentOS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span></span></code></pre></div><p>Tests should cover response contracts, Session ownership, pending/cancel/stop/timeout/unknown semantics, one active task, diagnostic Query, immutable bindings, no-POST recovery, revision recovery, evidence, version-scoped episodes, archive attacks, transactional rollback, Registry verification, Runtime health/switching, and mocked workflows. Concrete hardware/simulator tests are conditional on independently installed matching artifacts and Dora availability.</p><h2 id="next-reading" tabindex="-1">Next reading <a class="header-anchor" href="#next-reading" aria-label="Permalink to &quot;Next reading&quot;">​</a></h2><ul><li><a href="/docs/forge/README">Forge Tool API Integration Contract</a></li><li><a href="/docs/user_development_guide/README_en">Integration Development Guide</a></li><li><a href="/docs/en/05-agent-experience-and-skill-evolution">Agent Experience and Skill Evolution</a></li></ul>`,53)])])}const g=t(n,[["render",s]]);export{u as __pageData,g as default};
